"""Train-only held-week diagnostic: does incoming direction add next-zone information?"""
from base_replanteo import *
import math

def main():
 start=time.time();d=read(OUT/'datos_semi_markov/protocolo.json');z=np.load(OUT/'datos_semi_markov/runs_train.npz');cells=z['cell'].astype(np.int32);offset=z['run_offsets'];trip=z['trip_train_index'];valid=np.unpackbits(z['outgoing_valid_bits'])[:len(cells)].astype(bool);tr=dict(np.load(DATA/'train_x.npz'));sx=111195*np.cos(np.deg2rad(41.16));dx=(tr['d_lon']+8.62)*sx;dy=(tr['d_lat']-41.16)*111195;time0=tr['timestamp'];N=d['N'];ng=N*8*4;counts=np.zeros((ng,48),np.uint32);heading=np.zeros((ng*5,48),np.uint32);global_count=np.zeros((32,48),np.uint32);days=time0//86400;firstday=int(days.min());diff_day=np.zeros(int(days.max()-firstday+1));day_n=np.zeros(len(diff_day),np.int64);ns=0;fitn=0;acc0=0;acc1=0;loss0=0.;loss1=0.
 def batch(first,last):
  ri=np.arange(first,last);ti=np.searchsorted(offset,ri,side='right')-1;ix=trip[ti];terminal=ri==offset[ti+1]-1;cur=cells[ri];nxt=cells[np.minimum(ri+1,len(cells)-1)];a=nxt//d['ny']-cur//d['ny'];b=nxt%d['ny']-cur%d['ny'];code=(a+3)*7+b+3;act=code-(code>24);ok=valid[ri]&(~terminal)&(cur<N)&(nxt<N)&(np.abs(a)<=3)&(np.abs(b)<=3)&(code!=24);ri=ri[ok];ti=ti[ok];ix=ix[ok];cur=cur[ok];act=act[ok];x=d['x0']+(cur//d['ny']+.5)*d['cell_m'];y=d['y0']+(cur%d['ny']+.5)*d['cell_m'];vx=dx[ix]-x;vy=dy[ix]-y;direction=(np.floor((np.arctan2(vy,vx)+math.pi/8)/(math.pi/4)).astype(int)%8);distance=np.digitize(np.sqrt(vx*vx+vy*vy),[500,1500,4000]);group=(cur*8+direction)*4+distance;prev=cells[np.maximum(ri-1,0)];pa=cur//d['ny']-prev//d['ny'];pb=cur%d['ny']-prev%d['ny'];inc=(np.floor((np.arctan2(pb,pa)+math.pi/4)/(math.pi/2)).astype(int)%4);known=(ri>offset[ti])&(prev<N)&valid[np.maximum(ri-1,0)];inc=np.where(known,inc,4);hgroup=group*5+inc;fold=(time0[ix]//(7*86400))%5;day=days[ix]-firstday;return group,hgroup,direction*4+distance,act,fold,day
 for first in range(0,len(cells),200000):
  g,h,c,a,f,day=batch(first,min(first+200000,len(cells)));fit=f!=0;np.add.at(counts,(g[fit],a[fit]),1);np.add.at(heading,(h[fit],a[fit]),1);np.add.at(global_count,(c[fit],a[fit]),1);fitn+=int(fit.sum())
 base_n=counts.sum(1);head_n=heading.sum(1);gp=(global_count.astype(float)+1)/(global_count.sum(1,keepdims=True)+48)
 for first in range(0,len(cells),200000):
  g,h,c,a,f,day=batch(first,min(first+200000,len(cells)));held=f==0;g=g[held];h=h[held];c=c[held];a=a[held];day=day[held];p0=(counts[g]+20*gp[c])/(base_n[g,None]+20);p1=(heading[h]+20*p0)/(head_n[h,None]+20);row=np.arange(len(a));l0=-np.log(p0[row,a]);l1=-np.log(p1[row,a]);loss0+=l0.sum();loss1+=l1.sum();acc0+=int((p0.argmax(1)==a).sum());acc1+=int((p1.argmax(1)==a).sum());ns+=len(a);np.add.at(diff_day,day,l1-l0);np.add.at(day_n,day,1)
 keep=day_n>0;ss=diff_day[keep];nn=day_n[keep];rg=np.random.default_rng(1729);ix=rg.integers(len(nn),size=(3000,len(nn)));ci=np.quantile(ss[ix].sum(1)/nn[ix].sum(1),[.025,.975]);result=dict(kind='Train-only held-week next-zone diagnostic, NOT travel-time MAE',fit_moves=fitn,held_moves=ns,held_rule='UTC departure week modulo5 equals0',conditioning='Current cell, destination bearing8 bins and distance4 bins; add incoming direction4 plus unknown initial mode',baseline_NLL_nats=float(loss0/ns),with_direction_NLL_nats=float(loss1/ns),delta_nats=float((loss1-loss0)/ns),delta_CI95_by_day=ci,baseline_top1=float(acc0/ns),with_direction_top1=float(acc1/ns),selection_used_actual_Validation=False,Validation_or_Test_paths_decoded=False,Test_access=False,seconds=time.time()-start,code_sha256=sha(__file__),conclusion='Measures whether a direction-aware state is justified before expanding the generative process. Not evidence of a duration MAE improvement.')
 write(OUT/'diagnostico_direccion.json',result);print(json.dumps(result,default=lambda v:v.tolist() if isinstance(v,np.ndarray) else str(v)),flush=True)
if __name__=='__main__':main()
